<?php require __DIR__.'/lib/bootstrap.php';$user=require_auth();$date=$_GET['date']??date('Y-m-d');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date))$date=date('Y-m-d');if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$status=$_POST['status']??'';if(in_array($status,['pendente','confirmado','concluido','cancelado'],true)){$q=db()->prepare('UPDATE appointments SET status=? WHERE id=? AND user_id=?');$q->execute([$status,$id,$user['id']]);flash('Status do agendamento atualizado.');}redirect('agendamentos.php?date='.urlencode($date));}$items=appointments_for((int)$user['id'],$date);$services=services_for((int)$user['id']);require __DIR__.'/includes/shell-top.php';?>
<h1 class="h1">Agenda</h1><p class="muted">Acompanhe os horários marcados pelas suas clientes.</p><div class="tabs"><?php foreach([-1=>'-1 dia',0=>'Hoje',1=>'+1 dia'] as $offset=>$label):$d=date('Y-m-d',strtotime(($offset>=0?'+':'').$offset.' day'));?><a class="<?= $date===$d?'active':'' ?>" href="?date=<?= $d ?>"><?= e($label) ?> · <?= date('d/m',strtotime($d)) ?></a><?php endforeach; ?></div>
<div class="card"><?php if(!$items): ?><p class="muted" style="text-align:center;padding:28px">Nenhum horário marcado para este dia.</p><?php else: foreach($items as $a): ?><div class="list-row"><div class="grow"><b><?= e($a['client_name']) ?></b><div class="muted"><?= e($a['service_name']) ?> · <?= e(substr($a['start_time'],0,5)) ?> · <?= brl((float)$a['price']) ?></div><a class="muted" href="https://wa.me/<?= preg_replace('/\D/','',$a['client_whatsapp']) ?>" target="_blank" rel="noopener">WhatsApp da cliente ↗</a></div><form method="post"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$a['id'] ?>"><input type="hidden" name="status" value="<?= $a['status']==='confirmado'?'concluido':'confirmado' ?>"><button class="btn light"><?= $a['status']==='confirmado'?'Concluir':'Confirmar' ?></button></form></div><?php endforeach; endif; ?></div>
<h2 style="font:800 20px 'Bricolage Grotesque';margin-top:28px">Como receber novos horários</h2><p class="muted">Compartilhe sua página pública. As clientes escolhem um serviço e enviam a solicitação diretamente para sua agenda.</p>
